  document.addEventListener('input',e=>{const input=e.target;if(input.dataset.change==='inspect'){ui.chartIndex=+input.value;if(ui.chartKind==='month'){const r=selected(),months=[];let m=ui.chartAnchor||r.period;for(let i=0;i<6;i++){months.unshift(m);m=PB.prevMonth(m)}const period=months[ui.chartIndex],value=PB.reading(state,period)?.[ui.resource];$('#inspect-value').textContent=PB.shortMonth(period)+' · '+(value===undefined?'Missing':number(value,2)+' '+(ui.resource==='water'?'m³':'kWh'));input.setAttribute('aria-valuetext',$('#inspect-value').textContent);for(const [i,b]of [...$('#content').querySelectorAll('.bar-slot')].entries()){b.classList.toggle('active',i===ui.chartIndex);b.setAttribute('aria-pressed',String(i===ui.chartIndex))}}else{const r=selected(),vals=PB.breakdown(r,ui.resource,ui.chartKind),v=vals[ui.chartIndex]/(ui.chartKind==='hour'?r.days:1);$('#inspect-value').textContent=(ui.chartKind==='day'?ui.chartIndex+1:String(ui.chartIndex).padStart(2,'0')+':00')+' · '+number(v,Math.abs(v)<.1?3:2)+' '+(ui.resource==='water'?'m³':'kWh');input.setAttribute('aria-valuetext',$('#inspect-value').textContent)}}if(input.dataset.change==='price-inspect'){const index=+input.value;ui.modal.priceIndex=index;const price=PB.price(state,PB.fromLocal(ui.modal.draft.date+'T'+String(index).padStart(2,'0')+':00'));$('#price-value').textContent=String(index).padStart(2,'0')+':00 · '+PB.money(price)+' DKK/kWh';input.setAttribute('aria-valuetext',$('#price-value').textContent)}});
